import Foundation
import XCTest
@testable import LKSync
@testable import LKStore

/// RewardRules (LKStore/RewardRules.swift) against vectors/rewards.json – generated by running the real web Game.xpFor / repCut.
final class RewardsVectorTests: XCTestCase {
    func testXPRConstants() throws {
        let x = try XCTUnwrap(try Vectors.load("rewards.json")["XPR"]?.object)
        func i(_ k: String) -> Int { Int(x[k]?.double ?? -1) }
        XCTAssertEqual(i("pick"), RewardRules.pick); XCTAssertEqual(i("type"), RewardRules.type); XCTAssertEqual(i("write"), RewardRules.write)
        XCTAssertEqual(i("say"), RewardRules.say); XCTAssertEqual(i("hard"), RewardRules.hard); XCTAssertEqual(i("set"), RewardRules.set)
        XCTAssertEqual(i("exam"), RewardRules.exam); XCTAssertEqual(i("sec"), RewardRules.sec); XCTAssertEqual(i("perfect"), RewardRules.perfect)
        XCTAssertEqual(i("min"), RewardRules.min); XCTAssertEqual(i("talk"), RewardRules.talk); XCTAssertEqual(i("essay"), RewardRules.essay)
        XCTAssertEqual(i("learn"), RewardRules.learn); XCTAssertEqual(i("step"), RewardRules.step); XCTAssertEqual(i("great"), RewardRules.great)
        XCTAssertEqual(i("pass"), RewardRules.pass); XCTAssertEqual(i("cap"), RewardRules.cap); XCTAssertEqual(i("game"), RewardRules.game)
        XCTAssertEqual(x["card"]?.array?.map { Int($0.double ?? -1) }, RewardRules.card)
    }

    func testXpForCases() throws {
        let cases = try XCTUnwrap(try Vectors.load("rewards.json")["cases"]?.array)
        XCTAssertGreaterThan(cases.count, 50)
        var bad: [String] = []
        for c in cases {
            let kind = c["kind"]?.string ?? "", a = c["args"] ?? .object([:]), want = Int(c["xp"]?.double ?? -1)
            func n(_ k: String) -> Double? { a[k]?.double }
            func b(_ k: String) -> Bool { (a[k] ?? .null).truthy }
            let got = RewardRules.xp(kind, right: Int(n("right") ?? 0), total: Int(n("total") ?? 0), mode: a["mode"]?.string, hard: b("hard"),
                                     hints: Int(n("hints") ?? 0), score: n("score"), paid: b("paid"), words: n("words") ?? 0,
                                     sections: Int(n("sections") ?? 0), isNew: b("isNew"), again: b("again"))
            if got != want { bad.append("\(kind) \(a.stableString): \(got) ≠ \(want)") }
        }
        XCTAssertTrue(bad.isEmpty, bad.joined(separator: " ¦ "))
    }

    func testRepCut() throws {
        let rows = try XCTUnwrap(try Vectors.load("rewards.json")["repCut"]?.array)
        XCTAssertGreaterThan(rows.count, 10)
        for r in rows {
            let xp = Int(r["xp"]?.double ?? -1), c = Int(r["count"]?.double ?? -1), out = Int(r["out"]?.double ?? -1)
            XCTAssertEqual(RewardRules.repCut(xp: xp, count: c), out, "repCut(\(xp),\(c))")
        }
    }
}
